// CertStudy service worker: offline-first.
// precache.js (generated by tools/build.mjs) defines self.CERTSTUDY_BUILD = { id, files }. The cache name carries the build id, so a
// new build installs side by side and WAITS until the page asks it to take over (the "Update" prompt), which keeps a running exam
// from being reloaded underneath the learner.
importScripts('precache.js');

const BUILD = self.CERTSTUDY_BUILD;
const CACHE = `certstudy-${BUILD.id}`;
const abs = (path) => new URL(path, self.registration.scope).href;

async function precache() {
  const cache = await caches.open(CACHE);
  // cache: 'reload' bypasses the HTTP cache so a stale copy is never precached.
  await Promise.all(BUILD.files.map(async (path) => {
    const res = await fetch(new Request(abs(path), { cache: 'reload' }));
    if (!res.ok) throw new Error(`Precache failed for ${path} (${res.status})`);
    await cache.put(abs(path), res);
  }));
  const index = await cache.match(abs('index.html'));
  if (index) await cache.put(abs('./'), index.clone());
}

// A registration can outlive its cache (storage cleared, or "Clear offline cache" racing the unregister), and a hard reload leaves the
// page uncontrolled. The page then asks this worker to repair its cache if needed and take control again.
async function heal() {
  const cache = await caches.open(CACHE);
  if (!(await cache.match(abs('index.html')))) await precache();
  await self.clients.claim();
}

self.addEventListener('install', (event) => {
  event.waitUntil(precache());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith('certstudy-') && key !== CACHE) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  const type = event.data && event.data.type;
  if (type === 'SKIP_WAITING') self.skipWaiting();
  else if (type === 'CLAIM') event.waitUntil(heal().catch(() => {}));
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (request.mode === 'navigate') {
    event.respondWith(caches.open(CACHE).then((cache) => cache.match(abs('index.html'))).then((hit) => hit || fetch(request)));
    return;
  }
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const hit = await cache.match(request, { ignoreSearch: true });
    if (hit) return hit;
    try {
      const res = await fetch(request);
      if (res.ok && res.type === 'basic') cache.put(request, res.clone());
      return res;
    } catch {
      return new Response('Offline', { status: 503, statusText: 'Offline' });
    }
  })());
});
